// Deleted report is removed and cannot be re-deleted (integration)
// Generated by the QA spec generator (rung 2) — deterministic assembly; do not hand-edit.

import { test, expect } from '../../../fixtures';

test('TC-144: Deleted report is removed and cannot be re-deleted (integration)', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  await loginAs('admin');
  const reports: { id: number }[] = await (await api.get('/api/reports')).json();
  const reportId = reports[0].id;  // first seeded report
  const res = await api.delete(`/api/reports/${reportId}`);
  expect(res.status()).toBe(204);
  // Expected (full): First delete returns 204
  const res2 = await api.get(`/api/reports/${reportId}/detail`);
  expect(res2.status()).toBe(404);
  // Expected (full): Returns 404 (report gone)
  const res3 = await api.delete(`/api/reports/${reportId}`);
  expect(res3.status()).toBe(404);
  // Expected (full): Second delete returns 404
});
